'use strict';
// Writes docs/vpaa-conformance/e2e/E2E-REPORT.md from results.json (generated: do not edit by hand).
const fs = require('node:fs');
const path = require('node:path');
const dir = path.resolve(__dirname, '../../docs/vpaa-conformance/e2e');
const { summary, results } = JSON.parse(fs.readFileSync(path.join(dir, 'results.json'), 'utf8'));
const esc = (t) => String(t).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const known = results.flatMap((r) => r.checks.filter((c) => c.known).map((c) => ({ scenario: r.id, ...c })));
const lines = [];
lines.push('# Browser E2E report (LOCAL E2E)', '', '> Generated by `npm run test:e2e` (`scripts/e2e/run-e2e.cjs`). Do not edit by hand.', '');
lines.push(`**Label: ${summary.label}**`, '');
lines.push(`Browser: ${summary.browser} · Node ${summary.node} · finished ${summary.finishedAt}`, '');
lines.push('| | |', '|---|---|', `| Scenarios | ${summary.scenarios.passed} passed, ${summary.scenarios.failed} failed, of ${summary.scenarios.total} |`, `| Checks | ${summary.checks.passed} passed of ${summary.checks.total}; ${summary.checks.knownDefects || 0} known application defect(s) recorded |`, `| Provider requests (all answered by the scripted double) | ${summary.providerRequests} |`, `| Requests that tried to leave the machine | ${summary.blockedNetwork} |`, '');
lines.push('## What this is and is not', '', '- **Is:** a real Edge/Chromium browser driving the real React production build over https, through a TLS reverse proxy, to the real Express server running as `NODE_ENV=staging` (Secure cookies, explicit CORS origin, trusted proxy, fail-closed secrets), against a scratch MySQL database built from `init.js` plus every migration and filled with synthetic data only.', '- **Is not:** a staging E2E (no staging host exists), a test of Claude (the provider is a scripted double), or an academic-accuracy check.', '- Steps 2–6 of the Syllabus Builder were saved through the real API from the browser session; Step 1, the review step, the checker, submission and every administrator action were driven through the UI.', '');
lines.push('## Scenarios', '', '| ID | Result | Scenario | Checks |', '|---|---|---|---|');
for (const r of results) lines.push(`| ${r.id} | ${r.status} | ${esc(r.title)} | ${r.checks.filter((c) => c.ok).length}/${r.checks.length} |`);
lines.push('');
if (known.length) { lines.push('## Application defects found (reproducible)', ''); for (const k of known) lines.push(`- **${k.known}** (${k.scenario}): ${esc(k.message)}`); lines.push(''); }
lines.push('## Checks', '');
for (const r of results) {
  lines.push(`### ${r.id} — ${esc(r.title)}`, '');
  for (const c of r.checks) lines.push(`- ${c.ok ? '✔' : c.known ? '⚠' : '✖'} ${esc(c.message)}`);
  for (const n of r.notes.filter((x) => !/^(page (text|tail)|syllabus-check calls|failed responses|recommendation card|buttons|after Accept)/.test(x))) lines.push(`  - note: ${esc(n).slice(0, 400)}`);
  if (r.evidence.length) lines.push('', 'Evidence: ' + r.evidence.map((e) => `[${path.basename(e)}](${path.basename(e)})`).join(', '));
  lines.push('');
}
fs.writeFileSync(path.join(dir, 'E2E-REPORT.md'), lines.join('\n'));
console.log('wrote docs/vpaa-conformance/e2e/E2E-REPORT.md');
